export const ASCENT_STAGE = AERO.ascentStage;

/** Identity to show for a pillar. Until cutover the tutoring network is still "Swift Skills" unless the stage is ascent-internal. */
export function aeroBrand(key, stage) {
  const b = AERO.brands[key];
  if (!b) throw new Error('Unknown Aero brand: ' + key);
  const legacy = b.legacy && stage !== ASCENT_STAGE ? b.legacy : null;
  const s = legacy || b;
  return {
    key, paletteKey: legacy ? legacy.key : key, legacy: !!legacy,
    name: s.name, code: s.code, role: s.role, domain: s.domain, url: s.url,
    primary: s.primary, secondary: s.secondary, tertiary: s.tertiary,
  };
}

/** Locked artwork for a pillar: { viewBox, markup }. */
export function aeroLogo(key, variant, stage) {
  const b = AERO.brands[key];
  if (!b) throw new Error('Unknown Aero brand: ' + key);
  if (b.legacy && stage !== ASCENT_STAGE) return { viewBox: b.legacy.viewBox, markup: b.legacy.mark };
  const markup = variant === 'origami' ? b.origami : variant === 'kinetic' ? b.kinetic : b.isometric;
  return { viewBox: '0 0 48 48', markup };
}

/** Rows for the ecosystem switcher. urls overrides a pillar's link (local previews). */
export function aeroSwitcher(current, stage, urls) {
  return AERO.switcher.map((key) => {
    const b = aeroBrand(key, stage);
    return { ...b, href: (urls && urls[key]) || b.url, current: key === current };
  });
}
